#include "pattern_project_host_bridge.h"
#include <string.h>
static const br_pp_host_config *config;
static int fault;
static int overlap(const void *a,size_t an,const void *b,size_t bn){uintptr_t x=(uintptr_t)a,y=(uintptr_t)b;return an&&bn&&(x<=y?y-x<an:x-y<bn);}
int br_pp_host_configure(const br_pp_host_config *c){if(!c||!c->store||!c->ops||!c->adapter||!c->adapter->work||!c->adapter->sector||!c->arena[0]||!c->arena[1]||!c->capacity[0]||!c->capacity[1]||!c->can_access||!c->new_project||!c->ops->quiescent||!c->ops->capture||!c->ops->validate||!c->ops->restore||!c->ops->export_bank||!c->ops->can_adopt||!c->ops->adopt||!c->ops->restore_pattern||overlap(c->arena[0],c->capacity[0],c->arena[1],c->capacity[1]))return PFS_INVALID;config=c;return PFS_OK;}
static int ready(unsigned id,int write){return config&&!fault&&id<=12&&config->can_access(config->context,id,write)==1&&config->ops->quiescent&&config->ops->quiescent(config->ops->context);}
int br_pp_host_scan(unsigned id,char name[13]){uint8_t h[20];unsigned i;int rc;fm1_project_adapter *a;if(!name||!ready(id,0))return PFS_INVALID;a=config->adapter;rc=pfs_reader_open(config->store,id,&a->reader,a->sector);if(rc)return rc;if(a->reader.length<=20||pfs_reader_read_at(&a->reader,0,h,sizeof h,a->sector)||memcmp(h,"FPA1",4)||h[17]>12||(id!=12&&h[17])||h[18]||h[19])return PFS_INVALID;for(i=0;i<13&&h[4+i];i++)if(h[4+i]<32||h[4+i]>126)return PFS_INVALID;if(!i||i==13)return PFS_INVALID;for(;i<13;i++)if(h[4+i])return PFS_INVALID;memcpy(name,h+4,13);return PFS_OK;}
int br_pp_host_working(void){if(!ready(12,1))return PFS_INVALID;return fm1_project_adapter_save(config->store,12,"WORKING",config->ops,config->adapter);}
int br_pp_host_save(unsigned id,const char *name){int rc,old;if(!ready(id,1)||id>=12)return PFS_INVALID;rc=fm1_project_adapter_save(config->store,id,name,config->ops,config->adapter);if(rc)return rc;old=config->adapter->current_slot;config->adapter->current_slot=(int)id;rc=br_pp_host_working();if(rc){config->adapter->current_slot=old;return FM1_PROJECT_WORKING_FAILED;}return PFS_OK;}
static int load_one(unsigned id){fm1_project_adapter *a;unsigned i;char name[13];if(!ready(id,0))return PFS_INVALID;a=config->adapter;if(!config->ops->export_bank(config->ops->context,&a->bank,a->live,&a->song))return PFS_INVALID;for(i=0;i<2;i++)if(!overlap(config->arena[i],config->capacity[i],a->bank.arena,a->bank.capacity))break;if(i==2)return PFS_FULL;a->arena=config->arena[i];a->arena_capacity=config->capacity[i];a->work->arena=a->arena;a->work->arena_capacity=a->arena_capacity;int rc=fm1_project_adapter_load(config->store,id,name,config->ops,a);if(rc==FM1_PROJECT_ROLLBACK_FAILED)fault=1;return rc;}
int br_pp_host_load(unsigned id){int rc;if(id>=12)return PFS_INVALID;rc=load_one(id);if(rc)return rc;return br_pp_host_working()==PFS_OK?PFS_OK:FM1_PROJECT_WORKING_FAILED;}
int br_pp_host_recover(int *slot){int rc;if(!slot)return PFS_INVALID;rc=load_one(12);if(rc)return rc;*slot=config->adapter->current_slot;return PFS_OK;}
int br_pp_host_init_project(void){if(fault){int rc=br_pp_host_reset_fault();if(rc)return rc;return br_pp_host_working()==PFS_OK?PFS_OK:FM1_PROJECT_WORKING_FAILED;}if(!ready(12,1))return PFS_INVALID;if(config->new_project(config->context)!=1){fault=1;return FM1_PROJECT_ROLLBACK_FAILED;}config->adapter->current_slot=-1;return br_pp_host_working()==PFS_OK?PFS_OK:FM1_PROJECT_WORKING_FAILED;}
int br_pp_host_reset_fault(void){if(!config||!config->ops->quiescent||!config->ops->quiescent(config->ops->context))return PFS_INVALID;if(config->new_project(config->context)!=1){fault=1;return FM1_PROJECT_ROLLBACK_FAILED;}config->adapter->current_slot=-1;fault=0;return PFS_OK;}

int br_pp_host_faulted(void){return fault!=0;}
